solution.solution.cpp:
class Digit
{
public:
    explicit Digit(int value) : m_value{ value } {}
    int value() const { return m_value; }

    Digit& operator++()
    {
        m_value = (m_value + 1) % 10;
        return *this;
    }

    Digit operator++(int)
    {
        const Digit old{ *this };
        ++(*this);
        return old;
    }

private:
    int m_value{};
};

unitTests:
TEST("prefix returns the new value") { Digit d{ 5 }; const Digit r{ ++d }; CHECK_EQ(d.value(), 6); CHECK_EQ(r.value(), 6); }
TEST("postfix returns the old value") { Digit d{ 5 }; const Digit r{ d++ }; CHECK_EQ(d.value(), 6); CHECK_EQ(r.value(), 5); }
TEST("wraps from 9 to 0") { Digit d{ 9 }; ++d; CHECK_EQ(d.value(), 0); Digit e{ 9 }; e++; CHECK_EQ(e.value(), 0); }
TEST("prefix can be chained") { Digit d{ 1 }; ++(++d); CHECK_EQ(d.value(), 3); }

